export function aidShockSvg(lang, kind, mobile = false) {
  if (!['fr', 'en'].includes(lang) || !AID_SHOCK_KINDS.includes(kind) || typeof mobile !== 'boolean') throw new TypeError('Invalid Aid shock figure variant');
  return snippets[kind + '-' + lang + '-' + (mobile ? 'mobile' : 'desktop')];
}
